// ==== Máscara de DRAMA sobre la cara (mesh_0): triste al inicio, feliz al SONREIR ====
// La textura triste es la que tiene mesh_0 en su material.
// La feliz vive en el plano oculto "textura_feliz" (solo para guardarla). Aqui se intercambian.
// AJUSTES
var SONIDO = "";            // mp3 opcional, ej. "assets/sonidos/drama.mp3" (vacio = sonido sintetizado)
var sad = null, happy = null, isHappy = false, pop = 0;

function start() {
	sad = this.material.map;
	var h = this.parent && this.parent.getObjectByName("textura_feliz");
	happy = h ? h.material.map : null;
}
function switchTo(v) {
	if (v === isHappy || !happy) return;
	isHappy = v; pop = 1;
	this.material.map = v ? happy : sad;
	if (window.folio) { if (SONIDO) window.folio.sfx.fileOr(SONIDO, "drama"); else window.folio.sfx.play("drama"); }
}
function smileStart() { switchTo.call(this, true); }    // sonries  -> máscara feliz
function smileEnd()   { switchTo.call(this, false); }   // dejas de sonreir -> vuelve la triste
